#!/bin/sh
# Generates the Drizzle schema from the Better Auth configuration (deterministic, do not edit by hand).
set -eu
cd "$(dirname "$0")/.."
out=server/db/schema/auth.ts
pnpm dlx auth@1.7.17 generate --config server/auth/auth.cli.ts --output "$out" --adapter drizzle --dialect postgresql -y
{ printf '// GENERATED by scripts/gen-auth-schema.sh (auth generate). Do not edit.\n'; cat "$out"; } > "$out.tmp"
mv "$out.tmp" "$out"
